window.PlatdoReleaseData=[{"id":"v13-island","version":13,"date":"2026-11-02","major":true,"title":"A new coastline for Platdo City","summary":"Visit the redesigned island, take off from Northpoint, and explore the expanded City and Drive catalogs.","details":["City has a new airport, roads, beachfront and connected service locations.","City and Drive have more vehicles and expanded controls. City uses L for the front brake and K for headlights by default.","Browse optional outfits, vehicle finishes and activity packs in the shop. Public purchases are marked Coming Soon."],"thumbnailAlt":"City beach on the redesigned island","thumbnail":"assets/images/205d863ffdcb74385a90.jpg"},{"id":"v11-home-phone","version":11,"date":"2026-10-28","major":true,"title":"Home, style and the city in your pocket","summary":"Your starter house connects a personal garage, wardrobe and functional phone to the rest of Platdo.","details":["Explore the furnished two-storey starter house and enter Drive with your current garage car.","Buy and equip clothing, save outfits, and share your appearance between City and Drive.","Take rear-camera and selfie photos, record and play videos, and keep albums in the phone gallery.","Shop for owned vehicles and arrange delivery with LINK. Customize vehicles at the mechanic and choose saved finishes in Drive.","Choose Touch or Keyboard independently for each game; City adds analog mobile movement and simultaneous driving and camera controls.","City and Drive skies include changing weather; City adds distant birds."],"thumbnailAlt":"The actual Platdo City starter house and front garden","thumbnail":"assets/images/2aed43d5ac43af8da53a.png"},{"id":"v10-injuries","version":10,"date":"2026-10-26","major":true,"title":"Crash occupants and localized impacts","summary":"City injury settings and physical Drive occupants respond to the actual impact.","details":["City graphics adds four injury-effect settings with localized impacts and bounded detached-part effects.","Drive gains configurable vehicle occupants and a Traffic drivers only override.","Occupants react to crashes using passive articulated bodies, cabin and road contacts, settling and windshield ejection.","Settings apply immediately and preserve your selected intensity through graphics recommendations."],"thumbnailAlt":"Passengers seated in an actual Platdo Drive touring car","thumbnail":"assets/images/a09aa4773af5f56d58e5.png"}];

/* Player-facing changelog. Search indexes each individual item as well as the heading. */
(function(releases){
  'use strict';
  const section=(title,...items)=>({title,items});
  releases.unshift({
    id:'v14-palm-cove',version:14,date:'2026-11-02',major:true,title:'Palm Cove opens',thumbnail:'assets/images/4440dcf9c30773ee9158.jpg',thumbnailAlt:'Palm Cove Casino entrance viewed from Coast Boulevard',
    summary:'Visit the casino on Coast Boulevard, tune a Free Drive run, or bring your saved games to another device.',
    sections:[
      section('Your account',
        'Create Account and Log In are separate choices on the main menu. You can keep playing locally without an account.',
        'Create an account with a public player name, private email address, password and password confirmation. Sign in using the email address.',
        'Show or hide both password fields. Mismatched passwords, invalid email addresses, incorrect credentials and rate limits have their own messages. Submitting twice is blocked while a request is running.',
        'New password accounts receive a verification email. Account settings can resend it. Forgot password sends a reset link and keeps the response private regardless of whether the address exists.',
        'Google players can add a password to their existing account. The game checks the new credentials against the same player ID before reporting success. Google sign-in and existing saves stay available.',
        'Phone sign-in uses country-code entry, a verification challenge, a six-digit code and a resend option. The configured SMS regions are the US and Canada. Delivery to real phones requires the project owner to enable Firebase billing.',
        'Anonymous sign-in gives the device a Firebase guest identity. An anonymous player can create a permanent password login on the same UID. Purchases require a permanent account.',
        'Game Center requires a native Apple game. The browser sign-in screen explains this restriction.',
        'Account settings lets you change your public nickname, update your picture or log out. Supported browsers keep your session across refreshes.'),
      section('Saves and privacy',
        'The startup loader now checks the account and its saves before preparing the games. Startup writes wait for the active owner.',
        'If a different account signs in through another tab, the current game is covered while the new player’s saves load. Restoring progress also stops an older tab from saving its previous state back over the restored games.',
        'Signed-out guests and individual accounts keep separate progress. Signing out restores the guest’s previous progress and device media.',
        'Load all progress reads all available saved games, premium activity records and settings together. A game that has never had a cloud save keeps its device copy. A previously synced cloud deletion can also be restored.',
        'Every restored save is checked before it replaces a device copy. The game backs up the device copy first and reloads once for the batch.',
        'When the cloud and device disagree, the account panel names the affected games. You can keep the conflicting device saves together. A newer intervening cloud revision requires another review.',
        'Sync now is still available for sending progress. Email addresses stay private. Passwords go directly to Firebase Authentication.'),
      section('Palm Cove Casino · the building',
        'Find the Palm Cove Casino map pin on Coast Boulevard near Seaglass Beach. Approach it on foot and walk through the glass entrance.',
        'The single-story hall is 24 by 18 metres. Its level entrance opens onto a clear central aisle, with roulette on the left, slots on the right and a lounge at the back.',
        'A cream facade, teal frames, coral accents, brass edging, entrance canopy and lit Palm Cove sign mark the building from the street.',
        'Inside are a welcome counter, a fictional-cash information board, planters, carpet borders, benches and lounge tables. Furniture and walls have collision.'),
      section('Palm Cove Casino · playing',
        'At the roulette table, choose red, black or green and type a whole-dollar wager. The colored pads have names and separate symbols.',
        'The physical wheel has 15 equal sectors: seven red, seven black and one green. A winning red or black wager returns twice the stake, green returns 14 times. Returns include the stake.',
        'The roulette spin lasts four seconds. The ball finishes in the same sector shown on the receipt.',
        'Eight slot cabinets face out from two back-to-back rows. Each has a stool, a spin control and three reel windows. Every cabinet uses the same odds.',
        'The three independently drawn reel symbols are cherry, bell and diamond. Three matching symbols return 5, 8 or 12 times the stake respectively. Other combinations return zero.',
        'The reels stop in sequence during a 2.8-second spin. The result in the actual cabinet matches the result in the interaction panel.',
        'Both games use your fictional City wallet. You can enter a custom wager starting at $1. Invalid amounts, bets above your balance and returns above the wallet limit are rejected.',
        'The round receipt and wallet change are saved together. Double-clicking, closing the panel or reloading during a spin cannot charge the same round twice. Each cabinet remembers its last result.',
        'Keyboard, mouse and touch can operate the stations. The casino has interaction views, room sounds and phone layouts for both orientations.'),
      section('City · Story and Sandbox',
        'Story streets now have no pedestrians, NPC-driven traffic, guards or police. Resuming an older Story save also clears saved NPCs.',
        'Story jobs that depended on an NPC now use radio check-ins, security targets, tracker stops or taxi parcels. Your position in the mission list is preserved.',
        'Story and Sandbox keep their own money, inventory, vehicles, garage and wardrobe. Story outfits, finishes and activity choices stay with Story. Account ownership and control settings still follow you.',
        'Open the garage from Pause or your phone, between jobs or during a mission. You can store or recover a vehicle from either entry point.',
        'City shows your public player name on the title and character screens. Changing your nickname in Account settings updates City too.'),
      section('Friends · finding each other',
        'Open Friends from the home menu, City or Drive menus, or the City phone. Both games use the same list. A recoverable account is required.',
        'Copy your own ten-character friend code. Search another code to see the matching public name and avatar. Private email addresses never appear in friend search.',
        'Send, accept, decline or cancel a request. When both people send a request to each other, they become friends once. You can remove friends, block players and unblock them later.',
        'Filter your list by name or code. Online friends appear first. Status shows whether a friend is online, playing solo, reconnecting or can be joined.',
        'Badges mark incoming requests and invitations. In-game invites identify who sent them and which game they are playing.'),
      section('Friends · shared free roam',
        'The computer host supports City and Drive Free Drive, with up to eight people. The public website shows a connection notice until a reachable host is configured.',
        'Friends Only admits eligible friends of the room owner. Invite Only requires a current invitation for your account. The owner can change privacy, remove or readmit players, or end the session.',
        'Invites expire after two minutes. A loading reservation holds a seat for 45 seconds. Disconnecting gives you 30 seconds to reconnect. Extra social tabs do not spawn extra characters.',
        'In shared City, players can walk, drive or ride in separate vehicle seats, see the same traffic and pedestrians, and use nearby doors.',
        'In shared Drive, players bring their own saved car and upgrades. They share traffic, collision impacts, barriers and loose road objects. Opening a menu leaves the room running. The shared HUD shows room information and uses free-roam prompts.',
        'The host keeps a separate record of each player’s free-roam time and distance. Joining or leaving takes a checkpoint. Solo missions, casino wagers, timed challenges and solo rewards remain in their own modes.'),
      section('Drive · traffic, drift records and garage',
        'Free Drive replaces named traffic presets with an exact slider from 0 to 500 cars.',
        'Traffic raises wrong-lane and drift payouts. The multiplier starts at 1× and increases by 0.01× per selected car.',
        'Graphics vehicle density is grayed out during that Free Drive run. Its description explains that it cannot be used in this game mode.',
        'Drive Statistics records your longest continuous drift by distance. It shows the car, duration and distance in metres together. Older saves start recording on their next drift.',
        'Garage access is available from the driving HUD, mobile More menu, map selection, pause menu, results and wreck screen.'),
      section('Drive · solo slow motion',
        'Press T to enter or leave slow motion. Up increases the simulation speed and Down decreases it. The five speeds are 10%, 25%, 50%, 75% and 90% of normal.',
        'All three actions are rebindable and have touch controls. Multiplayer uses normal speed. Challenges played in slow motion are unranked.'),
      section('Update Hub',
        'Full release notes are organized by feature. Search also matches the text of individual changes, including control defaults, payout rules and save behavior.')
    ]
  });
  if(!releases.some(r=>r.version===12))releases.push({id:'v12-living-hub',version:12,date:'2026-10-28',major:true,title:'A new home for Platdo',summary:'The startup menu moved to City with direct access to City and Drive.',details:['The in-game computer opens Jump, Swing, Code Platdo and God Core.','The shared Statistics and Updates pages bring records and news into the main menu.','Google sign-in and cloud saves were added to account settings.']});
})(window.PlatdoReleaseData);

